 val transactions=repository.transactions.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val transfers=repository.transfers.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val budgets=repository.budgets.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val debts=repository.debts.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val bills=repository.bills.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val savingsGoals=repository.savingsGoals.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val assets=repository.assets.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val householdMembers=repository.householdMembers.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val householdExpenses=repository.householdExpenses.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val householdBudgets=repository.householdBudgets.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val documents=repository.documents.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val notifications=repository.notifications.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val auditLogs=repository.auditLogs.withStartupFallback(emptyList()).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList());val currentUser=repository.currentUser.withStartupFallback(null).stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),null)
 private val _appLanguage=MutableStateFlow(WebI18n.read(application));val appLanguage:StateFlow<AppLanguage> = _appLanguage.asStateFlow();private val preferences=application.getSharedPreferences("bye_pro_finance_preferences",Application.MODE_PRIVATE);private val _isDarkMode=MutableStateFlow(preferences.getBoolean("dark_mode",true));val isDarkMode=_isDarkMode.asStateFlow();private val _primaryCurrency=MutableStateFlow(preferences.getString("currency_code","LYD")?:"LYD");val primaryCurrency=_primaryCurrency.asStateFlow();private val _timeZone=MutableStateFlow(preferences.getString("time_zone","Africa/Tripoli")?:"Africa/Tripoli");val timeZone=_timeZone.asStateFlow();private val _dateFormat=MutableStateFlow(preferences.getString("date_format","YYYY-MM-DD")?:"YYYY-MM-DD");val dateFormat=_dateFormat.asStateFlow();private val _numberFormat=MutableStateFlow(preferences.getString("number_format","1,234.56")?:"1,234.56");val numberFormat=_numberFormat.asStateFlow();private val _emailNotifications=MutableStateFlow(preferences.getBoolean("email_notifications",true));val emailNotifications=_emailNotifications.asStateFlow();private val _transactionAlerts=MutableStateFlow(preferences.getBoolean("transaction_alerts",true));val transactionAlerts=_transactionAlerts.asStateFlow();private val _billReminders=MutableStateFlow(preferences.getBoolean("bill_reminders",true));val billReminders=_billReminders.asStateFlow();private val _budgetAlerts=MutableStateFlow(preferences.getBoolean("budget_alerts",true));val budgetAlerts=_budgetAlerts.asStateFlow()
 fun setPrimaryCurrency(v:String){val n=v.trim().uppercase();if(n !in setOf("LYD","USD","EUR","GBP","SAR","AED","EGP"))return;_primaryCurrency.value=n;preferences.edit().putString("currency_code",n).apply()};fun setTimeZone(v:String){_timeZone.value=v;preferences.edit().putString("time_zone",v).apply()};fun setDateFormat(v:String){_dateFormat.value=v;preferences.edit().putString("date_format",v).apply()};fun setNumberFormat(v:String){_numberFormat.value=v;preferences.edit().putString("number_format",v).apply()};fun setEmailNotifications(v:Boolean){_emailNotifications.value=v;preferences.edit().putBoolean("email_notifications",v).apply()};fun setTransactionAlerts(v:Boolean){_transactionAlerts.value=v;preferences.edit().putBoolean("transaction_alerts",v).apply()};fun setBillReminders(v:Boolean){_billReminders.value=v;preferences.edit().putBoolean("bill_reminders",v).apply()};fun setBudgetAlerts(v:Boolean){_budgetAlerts.value=v;preferences.edit().putBoolean("budget_alerts",v).apply()}
 fun updateLocalProfile(u:UserEntity){viewModelScope.launch{runCatching{repository.updateCurrentUser(u)}}};private val _currentScreen=MutableStateFlow("dashboard");val currentScreen=_currentScreen.asStateFlow();private val _scannedReceipt=MutableStateFlow<ExtractedReceiptData?>(null);val scannedReceipt=_scannedReceipt.asStateFlow();private val _chatMessages=MutableStateFlow<List<ChatMessage>>(emptyList());val chatMessages=_chatMessages.asStateFlow();private val _isAiLoading=MutableStateFlow(false);val isAiLoading=_isAiLoading.asStateFlow()
 init{resetWelcomeMessage();viewModelScope.launch{runCatching{repository.accounts.first()};_accountsLoading.value=false}}
 private fun resetWelcomeMessage(){_chatMessages.value=listOf(ChatMessage("AI",WebI18n.tr("مرحباً بك في BYE PRO FINANCE! أنا مساعدك المالي الذكي. يمكنك سؤالي عن مصروفاتك، ميزانيتك، أو تحليل وضعك المالي بدقة.","Welcome to BYE PRO FINANCE! I am your AI Financial Assistant. Ask me anything about your cash flow, budgets, or savings goals.",_appLanguage.value)))}
 fun setScreen(v:String){_currentScreen.value=v};fun toggleLanguage(){setLanguage(if(_appLanguage.value==AppLanguage.AR)AppLanguage.EN else AppLanguage.AR)};fun setLanguage(v:AppLanguage){_appLanguage.value=v;WebI18n.write(getApplication(),v);resetWelcomeMessage()};fun setDarkMode(v:Boolean){_isDarkMode.value=v;preferences.edit().putBoolean("dark_mode",v).apply()};fun toggleTheme(){setDarkMode(!_isDarkMode.value)}
 fun addAccount(x:AccountEntity)=viewModelScope.launch{_accountActionFeedback.value=AccountActionFeedback("add",runCatching{repository.addAccount(x)}.isSuccess)};fun clearAccountActionFeedback(){_accountActionFeedback.value=null};fun updateAccount(x:AccountEntity)=viewModelScope.launch{repository.updateAccount(x)};fun deleteAccount(x:AccountEntity)=viewModelScope.launch{repository.deleteAccount(x)};fun archiveAccount(id:Long,v:Boolean)=viewModelScope.launch{_accountActionFeedback.value=AccountActionFeedback("account",runCatching{repository.archiveAccount(id,v)}.isSuccess)}
 fun addTransaction(x:TransactionEntity)=viewModelScope.launch{repository.addTransaction(x)};fun updateTransactionStatus(x:TransactionEntity,v:TransactionStatus)=viewModelScope.launch{repository.updateTransactionStatus(x,v)};fun deleteTransaction(x:TransactionEntity)=viewModelScope.launch{repository.deleteTransaction(x)};fun executeTransfer(a:Long,b:Long,c:Double,d:Double,e:String,f:String,g:String,h:(Boolean)->Unit)=viewModelScope.launch{h(repository.executeTransfer(a,b,c,d,e,f,g))};fun addBudget(x:BudgetEntity)=viewModelScope.launch{repository.addBudget(x)};fun updateBudget(x:BudgetEntity)=viewModelScope.launch{repository.updateBudget(x)};fun deleteBudget(x:BudgetEntity)=viewModelScope.launch{repository.deleteBudget(x)};fun addDebt(x:DebtEntity)=viewModelScope.launch{repository.addDebt(x)};fun updateDebt(x:DebtEntity)=viewModelScope.launch{repository.updateDebt(x)};fun debtPayments(id:Long):Flow<List<DebtPaymentEntity>>=repository.debtPayments(id);fun payDebt(id:Long,a:Double,n:String,p:Long=System.currentTimeMillis())=viewModelScope.launch{repository.recordDebtPayment(id,a,n,p)};fun deleteDebt(x:DebtEntity)=viewModelScope.launch{repository.deleteDebt(x)}
 fun addBill(x:BillEntity)=viewModelScope.launch{repository.addBill(x)};fun updateBill(x:BillEntity)=viewModelScope.launch{repository.updateBill(x)};fun markBillPaid(a:Long,b:Long)=viewModelScope.launch{repository.markBillPaid(a,b)};fun deleteBill(x:BillEntity)=viewModelScope.launch{repository.deleteBill(x)};fun addSavingsGoal(x:SavingsGoalEntity)=viewModelScope.launch{repository.addSavingsGoal(x)};fun updateSavingsGoal(x:SavingsGoalEntity)=viewModelScope.launch{repository.updateSavingsGoal(x)};fun contributeToSavings(a:Long,b:Double,c:Long)=viewModelScope.launch{repository.contributeToSavings(a,b,c)};fun deleteSavingsGoal(x:SavingsGoalEntity)=viewModelScope.launch{repository.deleteSavingsGoal(x)};fun addAsset(x:AssetEntity)=viewModelScope.launch{repository.addAsset(x)};fun updateAsset(x:AssetEntity)=viewModelScope.launch{repository.updateAsset(x)};fun deleteAsset(x:AssetEntity)=viewModelScope.launch{repository.deleteAsset(x)}
 fun addHouseholdMember(a:String,b:String,c:String,d:Double)=viewModelScope.launch{repository.addHouseholdMember(a,b,c,d)};fun updateHouseholdMember(x:HouseholdMemberEntity)=viewModelScope.launch{repository.updateHouseholdMember(x)};fun deleteHouseholdMember(x:HouseholdMemberEntity)=viewModelScope.launch{repository.deleteHouseholdMember(x)};fun addHouseholdExpense(a:String,b:Double,c:Long?,d:String,e:String=primaryCurrency.value,f:Long=System.currentTimeMillis(),g:Boolean=false,h:String="")=viewModelScope.launch{repository.addHouseholdExpense(a,b,c,d,e,f,g,h)};fun updateHouseholdExpense(x:HouseholdExpenseEntity)=viewModelScope.launch{repository.updateHouseholdExpense(x)};fun deleteHouseholdExpense(x:HouseholdExpenseEntity)=viewModelScope.launch{repository.deleteHouseholdExpense(x)};fun addHouseholdBudget(a:String,b:Double,c:String,d:String)=viewModelScope.launch{repository.addHouseholdBudget(a,b,c,d)};fun deleteHouseholdBudget(x:HouseholdBudgetEntity)=viewModelScope.launch{repository.deleteHouseholdBudget(x)}
 fun addDocument(x:DocumentEntity)=viewModelScope.launch{repository.addDocument(x)};fun deleteDocument(x:DocumentEntity)=viewModelScope.launch{repository.deleteDocument(x)};fun markNotificationRead(id:Long)=viewModelScope.launch{repository.markNotificationRead(id)};fun markAllNotificationsRead()=viewModelScope.launch{repository.markAllNotificationsRead()};fun deleteNotification(id:Long)=viewModelScope.launch{repository.deleteNotification(id)};fun clearNotifications()=viewModelScope.launch{repository.clearNotifications()}
 fun clearAiChat(){if(!_isAiLoading.value)resetWelcomeMessage()};fun askAiAssistant(q:String){if(q.isBlank()||_isAiLoading.value)return;_chatMessages.value+=ChatMessage("USER",q.trim());_isAiLoading.value=true;viewModelScope.launch{val modelFile=LocalAiModelManager.modelFile(getApplication());val r=if(modelFile.isFile){runCatching{LocalAiRuntime.ensureLoaded(getApplication(),modelFile.absolutePath);LocalAiRuntime.ask(buildLocalAiPrompt(q.trim()))}.getOrElse{error->if(_appLanguage.value==AppLanguage.AR)"تعذر تشغيل النموذج المحلي: ${error.message ?: "خطأ غير معروف"}. افتح تبويب النموذج المحلي للتحقق من تشغيله." else "The local AI model could not start: ${error.message ?: "Unknown error"}. Open the Local Model tab to check its status."}}else aiService.askAssistant(q.trim(),_appLanguage.value);_isAiLoading.value=false;_chatMessages.value+=ChatMessage("AI",r)}};private val _ocrError=MutableStateFlow<String?>(null);val ocrError=_ocrError.asStateFlow();fun scanReceipt(a:String?=null,b:String?=null)=viewModelScope.launch{aiService.parseReceiptImage(a,b,_appLanguage.value).onFailure{_ocrError.value=it.message}};fun clearScannedReceipt(){_scannedReceipt.value=null;_ocrError.value=null}
 private fun buildLocalAiPrompt(question:String):String {
  val accountRows=accounts.value.filter{!it.isArchived}.joinToString("\n"){ "- ${it.name}: ${it.balance} ${it.currency}" }.ifBlank{"لا توجد حسابات متاحة"}
  val transactionRows=transactions.value.filter{it.status==TransactionStatus.COMPLETED}.takeLast(40).joinToString("\n"){ "- ${it.type.name} | ${it.category} | ${it.amount} ${it.currency} | ${it.description.take(80)}" }.ifBlank{"لا توجد معاملات مكتملة"}
  val budgetRows=budgets.value.joinToString("\n"){ "- ${it.name} | ${it.category} | ${it.limitAmount} ${it.currency}" }.ifBlank{"لا توجد ميزانيات"}
  val debtRows=debts.value.joinToString("\n"){ "- ${it.name} | ${it.direction} | المتبقي ${it.remaining} ${it.currency} | الأصل ${it.principal}" }.ifBlank{"لا توجد ديون"}
  return """
أنت مساعد BYE PRO FINANCE المالي المحلي. حلّل فقط البيانات الواردة أدناه.
لا تخترع أرقاماً أو معاملات أو أسعار صرف. إذا كانت البيانات غير كافية فاذكر ذلك بوضوح.
الحسابات والأرصدة:
$accountRows

المعاملات المكتملة الأخيرة (حتى 40):
$transactionRows

الميزانيات:
$budgetRows

الديون:
$debtRows

سؤال المستخدم:
$question
""".trimIndent()
 }
 fun importTransactionsFromJson(v:String,c:(Result<Int>)->Unit)=viewModelScope.launch{c(runCatching{repository.importTransactions(FinanceExportService.transactionsFromJson(v))})};fun importTransactionsFromCsv(v:String,c:(Result<Int>)->Unit)=viewModelScope.launch{c(runCatching{repository.importTransactions(FinanceExportService.transactionsFromCsv(v))})};fun generateCsvExport()=FinanceExportService.transactionsToCsv(transactions.value);fun generateJsonExport()=FinanceExportService.transactionsToJson(transactions.value);fun restoreBackupFromJson(v:String,c:(Boolean)->Unit)=viewModelScope.launch{c(repository.restoreFromJson(v))}
}
private fun <T> Flow<T>.withStartupFallback(f:T):Flow<T>=catch{e->Log.e("BYE_PRO_FINANCE","Remote data stream failed",e);emit(f)}
